// Preserves distinct capacity failure and explicit one-time unchanged-input fresh attempt.
import fs from "node:fs";
import path from "node:path";
const file = process.argv[2], batch = JSON.parse(fs.readFileSync(file, "utf8")), attempts = batch.cases["B4.2"].attempts;
if (attempts.length !== 2) throw new Error("expected original failure plus exactly one authorized fresh retry");
const [old, retry] = attempts;
const record = { canonicalSha: batch.source.canonicalSha, packageVersion: batch.packageVersion, variant: "B4.2", decision: "Parent authorized exactly one original-input fresh retry after short backoff; no model/source/controller switch", original: { attemptId: old.attemptId, uuid: old.threadId, transportStatus: old.turns[0].transportStatus, error: "Selected model is at capacity. Please try a different model.", eventsFile: old.turns[0].eventsFile, inputSha256: old.turns[0].inputSha256, behaviorStatus: "UNKNOWN_NOT_RETROACTIVELY_PASSED" }, freshRetry: { attemptId: retry.attemptId, uuid: retry.threadId, transportStatus: retry.turns[0].transportStatus, inputSha256: retry.turns[0].inputSha256 }, originalFirstInputBytesIdentical: fs.readFileSync(old.turns[0].inputFile).equals(fs.readFileSync(retry.turns[0].inputFile)), actualModelUnchanged: JSON.stringify(old.turns[0].actualIdentity.models) === JSON.stringify(retry.turns[0].actualIdentity.models), separateReviewRequired: true };
if (!record.originalFirstInputBytesIdentical || !record.actualModelUnchanged) throw new Error("retry identity/input differs; preserve and diagnose");
fs.writeFileSync(path.join(batch.recordRoot, "capacity-attempt-record.json"), JSON.stringify(record, null, 2) + "\n");
console.log(JSON.stringify({ capacityRecordFile: path.join(batch.recordRoot, "capacity-attempt-record.json"), unchangedInput: true, noRetroactivePass: true }));

// Exact transport history only. Never retroactively changes a failed semantic status.
import fs from "node:fs";
import path from "node:path";
const file = process.argv[2], batch = JSON.parse(fs.readFileSync(file, "utf8"));
const records = ["B4.2", "B5.2"].map(variant => {
  const attempts = batch.cases[variant].attempts;
  if (attempts.length !== 2) throw new Error("exactly one fresh retry required per capacity-affected case");
  const [old, retry] = attempts;
  const errors = fs.readFileSync(old.turns[0].eventsFile, "utf8").split(/\r?\n/).filter(Boolean).map(s => JSON.parse(s)).filter(e => e.type === "error" || e.type === "turn.failed");
  const originalInputUnchanged = fs.readFileSync(old.turns[0].inputFile).equals(fs.readFileSync(retry.turns[0].inputFile));
  if (!originalInputUnchanged) throw new Error("first input changed; do not claim unchanged retry");
  return { variant, original: { attemptId: old.attemptId, uuid: old.threadId, inputSha256: old.turns[0].inputSha256, transportStatus: old.turns[0].transportStatus, errors, eventsFile: old.turns[0].eventsFile, semanticStatus: "UNKNOWN_NOT_RETROACTIVELY_PASSED" }, freshRetry: { attemptId: retry.attemptId, uuid: retry.threadId, inputSha256: retry.turns[0].inputSha256, recordedTurns: retry.turns.length, transportStatuses: retry.turns.map(t => t.transportStatus) }, originalInputUnchanged, originalAndRetryModels: [old.turns[0].actualIdentity.models, retry.turns[0].actualIdentity.models] };
});
const out = path.join(batch.recordRoot, "capacity-history.json");
fs.writeFileSync(out, JSON.stringify({ canonicalSha: batch.source.canonicalSha, packageVersion: batch.packageVersion, records, noModelSourceOrControllerSwitch: true, noRetroactivePass: true }, null, 2) + "\n");
console.log(JSON.stringify({ capacityHistoryFile: out, noRetroactivePass: true }));

