// Sequential real blocking runner; no grading or retries. This allocation is B3/B4/B5.
import fs from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
const root = path.dirname(fileURLToPath(import.meta.url)), batchFile = process.argv[2];
const plan = JSON.parse(fs.readFileSync(path.join(root, "plan.json"), "utf8"));
function batch() { return JSON.parse(fs.readFileSync(batchFile, "utf8")); }
function call(file, args) {
  return new Promise((resolve, reject) => {
    const proc = spawn(process.execPath, [path.join(root, file), ...args], { stdio: ["ignore", "pipe", "pipe"], shell: false, windowsHide: true });
    proc.stdout.on("data", s => process.stdout.write(s)); proc.stderr.on("data", s => process.stderr.write(s));
    proc.on("error", reject); proc.on("close", code => code === 0 ? resolve() : reject(new Error(`controller exited ${code}; no retry`)));
  });
}
const ids = batch().selectedIds;
if (ids.some(id => !["B3.1", "B3.2", "B4.1", "B4.2", "B5.1", "B5.2"].includes(id))) throw new Error("this runner is only the allocated B3/B4/B5 subset");
for (const id of ids) {
  let state = batch().cases[id];
  if (!state.attempts.length) await call("harness.mjs", ["start", "--batch", batchFile, "--variant", id]);
  while (true) {
    state = batch().cases[id]; const attempt = state.attempts.at(-1), count = attempt.turns.length;
    if (attempt.turns.at(-1)?.transportStatus !== "COMPLETE") throw new Error(`transport incomplete ${id}; preserve and stop`);
    if (count === state.plannedTurns) break;
    if (plan.variants.find(v => v.id === id).turns[count].includes("{label}") && !attempt.selection) await call("choose-first.mjs", [batchFile, id, "1"]);
    await call("harness.mjs", ["next", "--batch", batchFile, "--variant", id]);
  }
  process.stdout.write(JSON.stringify({ variantComplete: id, semanticStatus: "UNKNOWN_PENDING_INDEPENDENT_REVIEW" }) + "\n");
  await call("record-native-loading.mjs", [batchFile]);
}
await call("harness.mjs", ["inspect", "--batch", batchFile]);
await call("harness.mjs", ["summary", "--batch", batchFile]);
await call("operator-observations.mjs", [batchFile]);

